import fs from 'node:fs/promises';
import path from 'node:path';
import { TARGET_LABELS } from './copy.mjs';

// Normal delivery contains only posters and one copy document. HTML helpers
// remain solely for validating batches generated by the earlier layout.
export const ENTRY_FILE = '打开结果.html';
export const COPY_FILE = '发布文案.txt';
export const INTERNAL_DIR = '.internal';
export const STATE_FILE = '任务状态.json';
const TITLES = { 'meal-overview': '综合海报', 'ingredient-focus': '备料海报', 'meal-focus': '餐食海报', 'dining-scene': '用餐海报' };
const escape = value => String(value).replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;').replaceAll('"', '&quot;').replaceAll("'", '&#39;');
export function deliveryName(page) {
  const sequence = /^0[1-4]_[a-z_]+(_\d+)?\.png$/.exec(page.file)?.[1] ?? '';
  const index = { 'meal-overview': '01', 'ingredient-focus': '02', 'meal-focus': '03', 'dining-scene': '04' }[page.template];
  if (!index) throw new Error('未知交付模板');
  return `${index}_${TITLES[page.template]}${sequence}.png`;
}
export function copyText(copy) {
  return `配套文案（草稿）\n\n${Object.entries(copy.copy_outputs).map(([target, value]) => `【${TARGET_LABELS[target]}】\n\n${value}`).join('\n\n────────────\n\n')}\n`;
}
export function deliveryHtml(facts, pages, copy) {
  const generated = pages.filter(p => p.status === 'generated');
  const complete = generated.length && pages.every(p => p.status !== 'failed');
  const posters = generated.map(page => {
    const primary = page.outputFiles.find(f => f.format === 'png');
    const title = TITLES[page.template];
    const href = escape(encodeURIComponent(primary.file));
    return `<article class="poster"><a class="picture" href="${href}" target="_blank" rel="noopener" aria-label="查看${title}大图"><img src="${href}" alt="${escape(facts.brand)} · ${title}" width="1080" height="1440"></a><div class="poster-caption"><div><h3>${title}${page.file.match(/_(\d+)\.png$/)?.[1] ? ` · 第 ${Number(page.file.match(/_(\d+)\.png$/)[1])} 页` : ''}</h3><span>${page.assetIds.length} 张实拍 · 点击图片看大图</span></div><div class="downloads">${page.outputFiles.map(f => `<a class="button small" href="${escape(encodeURIComponent(f.file))}" target="_blank" rel="noopener">打开${page.outputFiles.length > 1 ? ` ${f.format.toUpperCase()}` : '原图'}</a>`).join('')}</div></div></article>`;
  }).join('\n');
  const targets = Object.entries(copy.copy_outputs);
  const tabs = targets.map(([target], i) => `<button class="tab" id="tab-${target}" role="tab" aria-selected="${i === 0}" aria-controls="panel-${target}" tabindex="${i === 0 ? 0 : -1}">${TARGET_LABELS[target]}</button>`).join('');
  const panels = targets.map(([target, value], i) => `<section role="tabpanel" id="panel-${target}" aria-labelledby="tab-${target}"${i ? ' hidden' : ''}><div class="copy-heading"><h3>${TARGET_LABELS[target]}</h3><button type="button" class="button primary copy-button" data-copy="copy-${target}">复制这段文案</button></div><textarea id="copy-${target}" aria-label="${TARGET_LABELS[target]}文案" readonly spellcheck="false" rows="${Math.min(18, Math.max(6, value.split('\n').length + 2))}">${escape(value)}</textarea></section>`).join('\n');
  return `<!doctype html>
<html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta http-equiv="Content-Security-Policy" content="default-src 'none'; img-src 'self' file:; style-src 'unsafe-inline'; script-src 'unsafe-inline'; connect-src 'none'; base-uri 'none'; form-action 'none'"><title>${escape(facts.brand)} · 餐食图文</title>
<style>
:root{color-scheme:light;--ink:#183c2a;--muted:#697567;--paper:#f7f5eb;--line:#d8decf;--green:#2e673e;--yellow:#f5de81}*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:var(--paper);color:var(--ink);font-family:"PingFang SC","Microsoft YaHei",sans-serif;font-size:1rem;line-height:1.6}a{color:inherit}button,textarea{font:inherit}button,a{-webkit-tap-highlight-color:transparent}button{cursor:pointer}a:focus-visible,button:focus-visible,textarea:focus-visible{outline:3px solid #bc7b10;outline-offset:4px}header{border-bottom:1px solid var(--line)}.wrap{width:min(100% - 2rem,76rem);margin-inline:auto}.topline{display:flex;align-items:center;justify-content:space-between;gap:1rem;padding-block:1.3rem}.brand{font-family:"Songti SC","Noto Serif CJK SC",serif;font-size:1.1rem;font-weight:700}.status{border:1px solid var(--line);border-radius:2rem;padding:.2rem .7rem;font-size:.875rem;white-space:nowrap}.intro{padding:2.4rem 0 1.8rem}.eyebrow{font-size:.875rem;letter-spacing:.14em;color:var(--muted)}h1{font-family:"Songti SC","Noto Serif CJK SC",serif;font-size:clamp(2.1rem,4vw,3.3rem);line-height:1.2;letter-spacing:.02em;margin:.55rem 0 1rem}p{margin:.5rem 0}.intro p{color:var(--muted)}.nav{display:flex;gap:.75rem;margin-top:1.2rem;flex-wrap:wrap}.button{display:inline-flex;align-items:center;justify-content:center;min-height:2.75rem;padding:.55rem 1.15rem;border:1px solid var(--green);border-radius:.45rem;background:transparent;text-decoration:none;color:var(--green);font-weight:600;white-space:nowrap}.primary{background:var(--green);color:#fff}.button:hover{background:#e9eddf}.primary:hover{background:#245331}.section-title{display:flex;align-items:baseline;gap:1rem;justify-content:space-between;flex-wrap:wrap;margin-bottom:1rem}h2{font-size:1.35rem;margin:0}.section-title span,.poster-caption span{font-size:.875rem;color:var(--muted)}.gallery{display:grid;grid-template-columns:minmax(0,1fr);gap:1.6rem}.poster{min-width:0}.picture{display:block;overflow:hidden;border-radius:.6rem;box-shadow:0 5px 18px #173d2210;line-height:0}.picture img{width:100%;height:auto;aspect-ratio:3/4;object-fit:contain}.poster-caption{display:flex;justify-content:space-between;align-items:center;gap:.5rem;padding:.8rem .1rem}h3{font-size:1.05rem;margin:0 0 .2rem}.small{font-size:.875rem;padding:.4rem .65rem;min-height:2.75rem}.downloads{display:flex;gap:.4rem;flex-wrap:wrap}.copy-section{margin:3.5rem 0}.tabs{display:flex;gap:.4rem;flex-wrap:wrap;border-bottom:1px solid var(--line);padding-bottom:.8rem}.tab{border:0;color:var(--muted);background:transparent;border-radius:.4rem;min-height:2.75rem;padding:.6rem 1rem}.tab[aria-selected="true"]{background:var(--yellow);color:var(--ink);font-weight:700}.copy-heading{display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:1rem;margin:1.5rem 0 .75rem}textarea{display:block;width:100%;resize:vertical;min-height:12rem;padding:1.2rem;border:1px solid var(--line);border-radius:.5rem;background:#fffef8;color:#26372b;line-height:1.9;overflow-wrap:anywhere}footer{border-top:1px solid var(--line);padding:1.5rem 0 2.5rem;color:var(--muted);font-size:.875rem}.toast{position:fixed;bottom:1.3rem;left:50%;transform:translateX(-50%);max-width:calc(100% - 2rem);padding:.8rem 1.2rem;background:#183c2a;color:white;border-radius:.6rem;box-shadow:0 4px 20px #0002}.toast:empty{display:none}[hidden]{display:none!important}@media(min-width:48rem){.gallery{grid-template-columns:repeat(2,minmax(0,1fr))}.wrap{width:min(100% - 4rem,76rem)}}@media(min-width:64rem){.gallery{grid-template-columns:repeat(3,minmax(0,1fr))}}@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}}@media print{.nav,.button,.tabs,.toast{display:none!important}[role="tabpanel"][hidden]{display:block!important}textarea{height:auto}.poster{break-inside:avoid}}
</style></head><body><header><div class="wrap topline"><span class="brand">${escape(facts.brand)}</span><span class="status">${complete ? '预览草稿' : '生成未完成'}</span></div></header>
<main class="wrap"><div class="intro"><div class="eyebrow">MEAL STORY</div><h1>餐食海报与文案</h1><p>${generated.length} 张海报 · ${targets.length} 类文案${facts.date ? ` · ${escape(facts.date)}` : ''}。海报已在当前文件夹，文案可以直接复制。</p><nav class="nav" aria-label="结果导航"><a class="button primary" href="#posters">查看海报</a><a class="button" href="#copy">复制文案</a><a class="button" href="${escape(encodeURIComponent(COPY_FILE))}" download="${COPY_FILE}" data-save-copy>保存全部文案</a></nav></div>
<section id="posters"><div class="section-title"><h2>海报</h2><span>原尺寸 1080 × 1440</span></div><div class="gallery">${posters || '<p>本次没有可生成的海报，请先核对照片分类与菜名。</p>'}</div></section>
<section id="copy" class="copy-section"><div class="section-title"><h2>配套文案</h2><span>选择平台，一键复制</span></div><div class="tabs" role="tablist" aria-label="文案平台">${tabs}</div>${panels}</section></main><footer><div class="wrap">此页可离线打开。移动时保留整个结果文件夹，海报和文案在同一目录。</div></footer><div id="toast" class="toast" role="status" aria-live="polite"></div>
<script>
document.querySelector('[data-save-copy]').addEventListener('click', event => {
  event.preventDefault();
  const sections = Array.from(document.querySelectorAll('[role="tabpanel"]')).map(panel => '【' + panel.querySelector('h3').textContent + '】\\n\\n' + panel.querySelector('textarea').value);
  const value = '配套文案（草稿）\\n\\n' + sections.join('\\n\\n────────────\\n\\n') + '\\n';
  const url = URL.createObjectURL(new Blob([value], { type: 'text/plain;charset=utf-8' }));
  const link = document.createElement('a'); link.href = url; link.download = '发布文案.txt'; document.body.append(link); link.click(); link.remove(); setTimeout(() => URL.revokeObjectURL(url), 60000);
});
const tabs = Array.from(document.querySelectorAll('[role="tab"]'));
function activate(tab) { for (const t of tabs) { const active = t === tab; t.setAttribute('aria-selected', String(active)); t.tabIndex = active ? 0 : -1; document.getElementById(t.getAttribute('aria-controls')).hidden = !active; } }
for (const [i, tab] of tabs.entries()) { tab.addEventListener('click', () => activate(tab)); tab.addEventListener('keydown', event => { let next; if (event.key === 'ArrowRight') next = (i + 1) % tabs.length; else if (event.key === 'ArrowLeft') next = (i - 1 + tabs.length) % tabs.length; else if (event.key === 'Home') next = 0; else if (event.key === 'End') next = tabs.length - 1; else return; event.preventDefault(); activate(tabs[next]); tabs[next].focus(); }); }
let toastTimer;
function notify(message) { document.getElementById('toast').textContent = message; clearTimeout(toastTimer); toastTimer = setTimeout(() => { document.getElementById('toast').textContent = ''; }, 4000); }
for (const button of document.querySelectorAll('[data-copy]')) button.addEventListener('click', async () => { const field = document.getElementById(button.dataset.copy); let copied = false; try { if (navigator.clipboard && navigator.clipboard.writeText) { await navigator.clipboard.writeText(field.value); copied = true; } } catch {} if (!copied) { field.focus(); field.select(); try { copied = document.execCommand('copy'); } catch {} } notify(copied ? '文案已复制' : '文案已选中，请按 ⌘C 或 Ctrl+C 复制'); });
</script></body></html>\n`;
}
export async function writeDelivery(output, copy) {
  await fs.writeFile(path.join(output, COPY_FILE), copyText(copy), { mode: 0o600 });
}
